#!/usr/bin/env bash
# GSZ step144 — Netflix engine STAGE 4: customer tiered code panel. A Netflix
# order's delivered account email (inventory_items.account_ref) is used to read
# that account's mail from the Accounts Portal (lib/nfMail) and show only the
# code types the plan tier allows (lib/netflixGate): Phone = sign-in + travel;
# TV = + update-household; Full = + password reset. Login-gated + ownership-checked.
# New routes/netflixCodes.js + 2 views (/account/codes hub, /account/order/:no/codes).
# Dashboard gets a "Netflix codes & households" link. No migration. Idempotent.
set -euo pipefail
GSZ=/opt/gsz; TS=$(date +%Y%m%d-%H%M%S); BK="$GSZ/.bak-step144-$TS"; TMP=$(mktemp -d)
PATCHED=(server.js views/account/dashboard.ejs)
NEW=(routes/netflixCodes.js views/account/codes_hub.ejs views/account/netflix_codes.ejs)
echo "==> step144: Netflix customer code panel"
mkdir -p "$BK"; for f in "${PATCHED[@]}"; do mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; done
NEWHAD=()
for f in "${NEW[@]}"; do if [ -f "$GSZ/$f" ]; then NEWHAD+=("$f"); mkdir -p "$BK/$(dirname "$f")"; cp "$GSZ/$f" "$BK/$f"; fi; done
echo "    backup: $BK"
restore(){
  echo "!! FAILED — restoring"
  for f in "${PATCHED[@]}"; do cp "$BK/$f" "$GSZ/$f"; done
  for f in "${NEW[@]}"; do keep=0; for h in "${NEWHAD[@]:-}"; do [ "$h" = "$f" ] && keep=1; done; if [ "$keep" = "1" ]; then cp "$BK/$f" "$GSZ/$f"; else rm -f "$GSZ/$f"; fi; done
  pm2 restart gsz >/dev/null 2>&1 || true; echo "!! restored."
}
trap 'restore' ERR
echo "==> writing new files"; mkdir -p "$GSZ/routes" "$GSZ/views/account"
echo "" | base64 -d > "$GSZ/routes/netflixCodes.js"
echo ""    | base64 -d > "$GSZ/views/account/codes_hub.ejs"
echo ""    | base64 -d > "$GSZ/views/account/netflix_codes.ejs"
echo "" | base64 -d > "$TMP/p.js"
echo "==> applying patches"; node "$TMP/p.js" "$GSZ"
echo "==> validating"; node --check "$GSZ/routes/netflixCodes.js"; node --check "$GSZ/server.js"
node -e "const ejs=require('$GSZ/node_modules/ejs');['views/account/codes_hub.ejs','views/account/netflix_codes.ejs','views/account/dashboard.ejs'].forEach(function(f){ejs.compile(require('fs').readFileSync('$GSZ/'+f,'utf8'),{filename:'$GSZ/'+f});console.log('    ejs ok '+f)})"
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
echo "==> waiting for app to come up"
CODE=000
for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] && echo "    homepage 200: OK (after ${i}s)" || { echo "    homepage $CODE after ${i}s"; false; }
trap - ERR; rm -rf "$TMP"
echo ""; echo "==> step144 OK ✅  Customers see their Netflix codes at Account → 'Netflix codes & households' (/account/codes → per-order panel). Codes are read live from the portal and shown by plan tier (Phone / TV / Full)."
